"use strict";(self.webpackChunkcallvault_docs=self.webpackChunkcallvault_docs||[]).push([["6063"],{15865(e){e.exports=JSON.parse('{"tag":{"label":"architecture","permalink":"/tags/architecture","allTagsPath":"/tags","count":3,"items":[{"id":"architecture/data-layer","title":"Data layer","description":"The phone\'s own database is the source of truth. Turn private cloud backup on and a copy of each recording, plus its call details, is kept as private files on CallVault\'s servers.","permalink":"/architecture/data-layer"},{"id":"architecture/web-native-split","title":"One codebase, two builds","description":"CallVault builds a native Android recorder and a web dashboard from a single Flutter codebase \u2014 kept apart by keeping device-only code out of the web build.","permalink":"/architecture/web-native-split"},{"id":"architecture/pipeline","title":"The sync pipeline","description":"A recording is usable the moment the call ends. Each track backs up on its own, retries on an increasing delay, and CallVault never removes a phone copy before that recording is synced and its checksum verified.","permalink":"/architecture/pipeline"}],"unlisted":false}}')}}]);